from langsmith import traceable, get_current_run_tree, tracing_context

MODELO = "gpt-5-nano"

@traceable(name="query_database", run_type="tool")
def query_database(query: str) -> str:
    run = get_current_run_tree()
    if run:                                         # uso 3: costo fijo de un tool
        run.set(usage_metadata={"total_cost": 0.002})   # valor de ejemplo
    return "[('Anvil 100 lb', 847.5)]"              # base de datos falsa

@traceable(run_type="llm", name="chat_completion")
def _call_llm(messages: list) -> str:
    run = get_current_run_tree()
    if run:                                         # uso 2: datos para calcular costo
        run.extra = {
            **(run.extra or {}),
            "metadata": {
                **(run.extra or {}).get("metadata", {}),
                "ls_provider": "openai",
                "ls_model_name": MODELO,
            },
        }
    return "El yunque de 100 lb cuesta $847.50"     # LLM falso

@traceable(name="Agent")
def chat(question: str, langsmith_extra: dict | None = None) -> dict:
    run = get_current_run_tree()
    run_id = str(run.id) if run else None           # uso 1: guardar el id para feedback
    datos = query_database("SELECT name, price FROM products")
    respuesta = _call_llm([question, datos])
    return {"answer": respuesta, "run_id": run_id}

base_meta = {"session_id": "conv-1", "scenario": 10, "customer_name": "Elmer Fudd"}
base_tags = ["Elmer Fudd", "scenario:10"]
csa_extra = {"langsmith_extra": {"metadata": {**base_meta, "agent_name": "csa"},
                                 "tags": [*base_tags, "csa"]}}

raices = []
with tracing_context(enabled="local"):
    resultado = chat("¿Cuánto cuesta el yunque?",
                     langsmith_extra={**csa_extra["langsmith_extra"], "on_end": raices.append})

def mostrar(run, nivel=0):
    md = {k: v for k, v in (run.extra or {}).get("metadata", {}).items() if k != "ls_method"}
    print("  " * nivel + f"{run.name} [{run.run_type}] tags={run.tags} metadata={md}")
    for hijo in run.child_runs:
        mostrar(hijo, nivel + 1)

mostrar(raices[0])
print("run_id devuelto == id de la raíz:", resultado["run_id"] == str(raices[0].id))

